# EXP-029 CPU-only pinned input preflight; no model execution.
import base64,io,zipfile,pathlib,subprocess,sys
p=pathlib.Path('/kaggle/working/preflight-code');p.mkdir(exist_ok=False)
blob=base64.b64decode('')
with zipfile.ZipFile(io.BytesIO(blob)) as z:
    assert set(z.namelist())=={'preflight.py','preflight_config.json'}
    z.extractall(p)
subprocess.run([sys.executable,'-u',str(p/'preflight.py')],check=True,timeout=3500)
